export const parseCmdArgDesc = (
		hCmdArgDesc: hashof<TArgDesc>
		): TCmdArgDetails => {

	const hFlagNames: hashof<string> = {}
	const hStrTypes:  hashof<string> = {}
	const hNumTypes:  hashof<string> = {}
	let minNonOpt = 0
	let maxNonOpt = 0

	for (const key of keys(hCmdArgDesc)) {
		assert(isIdentifier(key), `Bad key: ${key}`)
		const h = hCmdArgDesc[key]
		const errMsg = `Bad desc for ${key}: ${h}`
		if (('range' in h) && (key === '_')) {
			const [min, max] = h.range
			assert(isInteger(min) && isInteger(max), errMsg);
			[minNonOpt, maxNonOpt] = h.range
		}
		else if ('valType' in h) {
			switch(h.valType) {
				case 'string': {
					hStrTypes[key] = 'string';break;
				}
				case 'integer':case 'number': {
					hNumTypes[key] = h.valType;break;
				}
				default: {
					croak(errMsg)
				}
			}
		}
		else if ('flag' in h) {
			hFlagNames[h.flag] = key
		}
		else {
			croak(errMsg)
		}
	}
	return {hFlagNames, hStrTypes, hNumTypes, minNonOpt, maxNonOpt}
}

// ---------------------------------------------------------------------------

export const helpStr = (
		cmdName: string,
		hCmdArgDesc: hashof<TArgDesc>
		): string => {

	resetOneIndent(undef, spaces(3))
	const lLines = mkArray(keys(hCmdArgDesc), function*(key) {
		const h = hCmdArgDesc[key]
		if (key === '_') {
			assert(('range' in h), `Bad Desc for _: ${h}`)
			const {range, desc} = h
			const [min, max] = range
			if (nonEmpty(desc)) {
				yield `non-options: ${desc}`
			}
			else {
				yield "non-options:"
			}
			yield indented(`min: ${min}`)
			yield indented(`max: ${max}`)
		}
		else if ('flag' in h) {
			const {flag, desc} = h
			if (nonEmpty(desc)) {
				yield `-${flag}: ${desc}`
			}
			else {
				yield `-${flag}: ${key}`
			}
		}
		else if ('valType' in h) {
			const {valType, desc} = h
			if (nonEmpty(desc)) {
				yield `-${key}: ${valType} - ${desc}`
			}
			else {
				yield `-${key}: ${valType}`
			}
		}
	})
	return [
		'Usage:',
		indented(cmdName),
		...indented(lLines)
		].join('\n')
}

